const languageOriginals=new WeakMap();
function translatedUI(text){if(localizedLabels[text])return localizedLabels[text];const numbered=text.match(/^(\d+\. )(.+)$/);if(numbered&&localizedLabels[numbered[2]])return numbered[1]+localizedLabels[numbered[2]];return text.replace(/^Version (\d+)$/,'バージョン $1').replace(/^Good morning, /,'おはようございます、').replace(/^(\d+) weeks$/,'$1週間').replace(/^(\d+) hours$/,'$1時間')}
function applyInterfaceLanguage(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('script,style,textarea,[contenteditable="true"],.transcript-feed,pre'))continue;let saved=languageOriginals.get(node);if(!saved||node.nodeValue!==saved.last)saved={original:node.nodeValue};const key=saved.original.trim();const result=interfaceLanguage==='ja'?saved.original.replace(key,translatedUI(key)):saved.original;if(node.nodeValue!==result)node.nodeValue=result;saved.last=result;languageOriginals.set(node,saved)}document.documentElement.lang=interfaceLanguage;}
const languageObserver=new MutationObserver(()=>{languageObserver.disconnect();applyInterfaceLanguage();languageObserver.observe(document.body,{subtree:true,childList:true,characterData:true})});languageObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
const contextRecordingPage=blueprintPageRoutes.meetings;
blueprintPageRoutes.meetings=()=>contextRecordingPage();
function addRecordingContext(){if(!selected)return toast(interfaceLanguage==='ja'?'プロジェクトを選択してください。':'Select a project first.');if(current().approved)return toast(interfaceLanguage==='ja'?'新しいSRSドラフトを開いてください。':'Open a new SRS draft before adding context.');if(!demoRecordingCount)return toast(interfaceLanguage==='ja'?'先に録音プレビューを開始してください。':'Start a recording preview first.');const text=jpMeeting.slice(0,demoRecordingCount).map(([speaker,en,ja])=>speaker+': '+en+'\n'+ja).join('\n\n');current().meeting=text;current().source='Meeting transcript · Demo';const marker='\n\n[Meeting context · Demo]\n';docs()[1]=docs()[1].split(marker)[0]+marker+text;current().reviewed=false;sectionIndex=1;stopDemoRecording();navigate('srs');toast(interfaceLanguage==='ja'?'会議の内容をSRSに追加しました。':'Meeting context added to SRS.');}
const setLanguageOriginal=setInterfaceLanguage;
setInterfaceLanguage=function(value){sectionSave();setLanguageOriginal(value);applyInterfaceLanguage()};
render();applyInterfaceLanguage();
